function authDisplayName(identity) {
    return isApiKeyIdentity(identity) ? "API key" : identity.email;
}
function authStatus(identity) {
    return isApiKeyIdentity(identity)
        ? "Authenticated with an API key"
        : `Logged in as ${identity.email}`;
}
/** Authentication options used after executable project configuration has loaded. */
export function createConnectedDevAuthenticationOptions(apiBaseUrl, timeoutMs = 10_000) {
    return {
        throwOnCredentialValidationUnavailable: true,
        transport: createCloudOnboardingTransport(apiBaseUrl, timeoutMs),
        timeoutMs,
    };
}
/** Host transport for source sync; responses remain streaming for large files. */
export function createConnectedDevSyncTransport(apiBaseUrl) {
    return createVeryfrontApiOriginBoundOutboundFetch(apiBaseUrl);
}
export async function preloadDevAuth(apiToken, projectDir) {
    const env = getEnvironmentConfig();
    const trust = resolveApiUrlTrust(env, null);
    const candidates = await resolveApiCredentialCandidatesForAuth(env, projectDir, true);
    const candidate = apiToken
        ? candidates.find((entry) => entry.apiToken === apiToken)
        : candidates[0];
    // Direct callers can supply an explicit token without loading it into the
    // process environment. That remains valid only when the repository did not
    // choose the destination. A repository-steered destination requires the
    // resolver's source-qualified token and its paired validation environment.
    if (!candidate && (!apiToken || trust.repositorySteered)) {
        return { identity: null, projects: [] };
    }
    const result = await fetchRemoteProjects(candidate?.apiToken ?? apiToken, candidate?.validationEnv ?? env);
    const identity = result.credentialType === "apiKey"
        ? result.error ? null : { authenticated: true, type: "apiKey" }
        : result.user;
    return { identity, projects: result.projects };
}
/**
 * Run the interactive login behind the `a` shortcut and report a refusal.
 *
 * The keyboard handler dispatches shortcuts without awaiting them, so a
 * rejection escapes as an unhandled promise rejection and tears the dev server
 * down. `login()` now refuses when a repository chose the API endpoint, and
 * that refusal is exactly the message the developer must read, so print it on
 * the dev output line instead of letting it escape.
 */
export async function loginForDevShortcut(attemptLogin = login) {
    try {
        return await attemptLogin();
    }
    catch (err) {
        console.log(`  ${errorColor("✗")} ${err instanceof Error ? err.message : String(err)}`);
        return null;
    }
}
/** Startup sync updates the linked source with ordinary push conflict guards. */
export function createConnectedDevSourceSync(projectDir, getApiBaseUrl, push = pushCommand) {
    return async (target) => {
        console.log("  Syncing project source for local development...");
        await push({
            projectDir,
            projectSlug: target.projectSlug,
            projectId: target.projectId,
            quiet: true,
            noAdoptPins: true,
            transport: createConnectedDevSyncTransport(getApiBaseUrl()),
        });
    };
}
export function createSelectedProjectPushOptions(projectDir, project) {
    return createStagedPushOptions(project.slug, projectDir);
}
/**
 * Starts the dev server on the first free port at or after `requestedPort`.
 *
 * Port 3000 is the most contended port on a developer machine, and the docs
 * tell readers to run a bare `veryfront dev`, so a taken port scans forward
 * rather than killing the command. Everything downstream - the MCP port, the
 * printed URL, the browser the demo opens - must key off the returned `port`
 * rather than the requested one, or a fall-forward points the user at the
 * process that caused the collision.
 *
 * Takes `start` as a callback so the whole scan costs one `DevServer.start()`:
 * probing is a bare bind/release, and a failed `start()` has already registered
 * watchers and reload subscriptions that only `stop()` releases.
 */
export async function startDevServerOnFreePort(requestedPort, start) {
    const port = await findAvailablePort(requestedPort);
    // Port 0 asked for any free port, so landing elsewhere took nothing away.
    if (requestedPort !== 0 && port !== requestedPort) {
        console.log();
        console.log(`  ${warning("!")} Port ${requestedPort} is in use, using ${port} instead`);
    }
    try {
        return { server: await start(port), port };
    }
    catch (error) {
        // Lost the race between probing the port and binding it.
        if (isPortInUseError(error)) {
            throw PORT_IN_USE.create({
                detail: `Port ${port} is already in use`,
                cause: error,
                context: { port },
            });
        }
        throw error;
    }
}
/**
 * Clears the shared on-disk ESM caches, but only if they are safe to remove.
 *
 * The caches live under the project's `.cache` directory, which every dev
 * server rooted at that project shares. A taken dev port is the signal that one
 * of them is already running and still serving modules it compiled, so the
 * clear is skipped rather than wiping that server's work out from under it -
 * the second `veryfront dev` falls forward to a free port and starts on a cache
 * it did not just destroy.
 *
 * The clear is also skipped when the project keeps a persistent local dev
 * cache. That cache stores compiled modules that reference these files, so
 * removing them makes every entry fail validation and turns each restart cold
 * again. Run `veryfront clean --cache` to reset both.
 *
 * Returns whether the clear ran. Takes `clear`, `probe`, and `persists` as
 * parameters so the decision can be tested without booting a dev server, the
 * same seam `startDevServerOnFreePort` uses.
 */
export async function clearLocalCachesIfPortFree(requestedPort, clear = clearAllLocalCaches, probe = isPortAvailable, persists = isPersistentLocalCacheEnabled) {
    if (!await probe(requestedPort))
        return false;
    if (persists())
        return false;
    await clear();
    return true;
}
export function devCommand(options) {
    return withSpan("cli.command.dev", async () => {
        const { port, portExplicit, projectDir, hmr = true, open = false, demoMode = false, clearLocalCaches = false, } = options;
        const displayOptions = captureDevDisplayOptions();
        const workerDisplayName = captureLocalWorkerName();
        captureHostApiEnvironment();
        trustOperatorConfiguredVeryfrontApiOrigins();
        let doneResolve;
        const done = new Promise((resolve) => {
            doneResolve = resolve;
        });
        const adapter = await runtime.get();
        let config;
        try {
            config = await getConfig(projectDir, adapter);
        }
        catch (error) {
            if (error instanceof Error && error.message.includes("not found")) {
                throw CONFIG_NOT_FOUND.create({
                    detail: "No veryfront.config.js found",
                    context: { projectDir },
                });
            }
            throw error;
        }
        const DEFAULT_DEV_PORT = 3000;
        // Use `portExplicit` when provided so that `PORT=3000` is honoured even
        // though 3000 equals the default — the old sentinel `port !== 3000` would
        // silently discard an explicit env-var request that happens to equal the
        // default value.  Fall back to the sentinel for callers that predate this
        // field.
        const finalPort = (portExplicit ?? port !== DEFAULT_DEV_PORT)
            ? port
            : (config?.dev?.port ?? port);
        const enableHMR = config?.dev?.hmr !== false && hmr;
        if (clearLocalCaches)
            await clearLocalCachesIfPortFree(finalPort);
        const env = getEnvironmentConfig();
        const isProxyMode = config?.fs?.veryfront?.proxyMode === true;
        let linkedProjectSlug = await resolveLinkedProjectSlug(projectDir, config?.projectSlug ?? config?.fs?.veryfront?.projectSlug ?? env.projectSlug);
        if (!linkedProjectSlug && !isProxyMode && isTTY() && isInteractive()) {
            await chooseCloudProject(projectDir);
            linkedProjectSlug = await resolveLinkedProjectSlug(projectDir);
        }
        let preflightIdentity = null;
        let runtimeAuth = await applyQualifiedRuntimeAuth(projectDir, linkedProjectSlug);
        const connectedTarget = await prepareConnectedDev(linkedProjectSlug, options.environment ?? "preview", {
            authenticate: async () => {
                preflightIdentity = await ensureAuthenticated(getEnvironmentConfig(), projectDir, createConnectedDevAuthenticationOptions(connectedDevApiBaseUrl(runtimeAuth.apiBaseUrl)));
                return Boolean(preflightIdentity);
            },
            sync: createConnectedDevSourceSync(projectDir, () => connectedDevApiBaseUrl(runtimeAuth.apiBaseUrl)),
            resolve: async (projectSlug, environmentName) => {
                runtimeAuth = await applyQualifiedRuntimeAuth(projectDir, projectSlug);
                runtimeAuth.apiBaseUrl = connectedDevApiBaseUrl(runtimeAuth.apiBaseUrl);
                if (!runtimeAuth.apiToken || !runtimeAuth.apiBaseUrl) {
                    throw new Error("Veryfront Cloud credentials are unavailable. Run veryfront login and retry.");
                }
                const controlPlane = createConnectedDevControlPlane({
                    apiUrl: runtimeAuth.apiBaseUrl,
                    apiToken: runtimeAuth.apiToken,
                    apiTokenSource: runtimeAuth.apiTokenSource,
                    projectSlug,
                });
                const project = await resolveConnectedDevProject(controlPlane, projectDir, {
                    apiUrl: runtimeAuth.apiBaseUrl,
                    apiToken: runtimeAuth.apiToken,
                    apiTokenSource: runtimeAuth.apiTokenSource,
                    projectSlug,
                });
                const environment = await controlPlane.getEnvironment(project.id, environmentName);
                if (!environment) {
                    throw new Error(`Environment "${environmentName}" does not exist in project "${project.slug}". Choose an existing environment with --env <name>.`);
                }
                await saveSharedProjectAssociation(projectDir, project.slug, runtimeAuth.apiBaseUrl);
                runtimeAuth = applyConnectedDevProjectSlug(runtimeAuth, project.slug);
                linkedProjectSlug = project.slug;
                return {
                    projectId: project.id,
                    projectSlug: project.slug,
                    environmentId: environment.id,
                    environmentName: environment.name,
                };
            },
        }, isProxyMode);
        const studioBase = connectedTarget
            ? connectedDevStudioBaseUrl(connectedDevApiBaseUrl(runtimeAuth.apiBaseUrl), displayOptions.studioUrl)
            : "";
        const disposeConnectedRuntime = connectedTarget && runtimeAuth.apiToken && runtimeAuth.apiBaseUrl
            ? installConnectedLocalRuntime({
                ...connectedTarget,
                workerDisplayName,
                apiToken: runtimeAuth.apiToken,
                apiBaseUrl: runtimeAuth.apiBaseUrl,
                studioUrl: studioBase,
            })
            : undefined;
        const initialAuthPromise = preloadDevAuth(runtimeAuth.apiToken, projectDir).catch(() => ({
            identity: null,
            projects: [],
        }));
        // Validate provider config and print warnings (framework returns plain text, CLI adds colors)
        const aiValidation = validateProviderConfig(config);
        if (aiValidation.warnings.length > 0) {
            console.log();
            for (const w of aiValidation.warnings) {
                console.log(`  ${warning("!")} ${w.replace(/\n/g, "\n    ")}`);
            }
            console.log();
        }
        if (config?.experimental?.precompileMDX) {
            const outputDir = join(projectDir, ".veryfront", "compiled");
            try {
                await compileAllMDX({ projectDir, outputDir, mode: "development" });
                void watchMDX({ projectDir, outputDir, mode: "development" });
            }
            catch {
                // MDX pre-compilation failed
            }
        }
        const shutdownController = new AbortController();
        let devServer = null;
        let mcpServer = null;
        // Sync state
        let identity = null;
        let projects = [];
        let selectedProject = null;
        let started;
        try {
            started = await startDevServerOnFreePort(finalPort, (port) => startDevServer({
                port,
                projectDir,
                enableHMR,
                enableFastRefresh: true,
                signal: shutdownController.signal,
            }));
        }
        catch (error) {
            await disposeConnectedRuntime?.();
            throw error;
        }
        devServer = started.server;
        const boundPort = started.port;
        const DEV_MCP_PORT_OFFSET = 2;
        const mcpPort = boundPort + DEV_MCP_PORT_OFFSET;
        try {
            mcpServer = await createMCPServer({ httpPort: mcpPort });
        }
        catch {
            // MCP server failed to start - non-fatal, continue without it
        }
        const authReady = initialAuthPromise.then((initialAuth) => {
            identity = initialAuth.identity;
            projects = initialAuth.projects;
        });
        void authReady;
        let keyboardHandler = null;
        let shuttingDown = false;
        const projectSelector = createProjectSelector({
            prepare: () => authReady,
            getProjects: () => projects,
            getSelectedProjectId: () => selectedProject?.id ?? null,
            pauseKeyboard: () => keyboardHandler?.stop(),
            resumeKeyboard: () => keyboardHandler?.start(),
            onEmpty: () => {
                if (!identity) {
                    console.log(`  Press ${brand("a")} to sign in`);
                    return;
                }
                console.log("  No projects found");
            },
            onInterrupt: () => void shutdown(),
            onSelect: (project) => {
                selectedProject = project;
            },
        });
        async function runSyncAction(action, successMsg) {
            try {
                await action();
                console.log(`  ✓ ${successMsg}`);
            }
            catch (err) {
                console.log(`  ${errorColor("✗")} ${err instanceof Error ? err.message : String(err)}`);
            }
        }
        async function shutdown() {
            if (shuttingDown) {
                if (!demoMode) {
                    console.log("  ! Stopping immediately. Run cancellation may not have been saved.");
                    exitProcess(1);
                }
                return;
            }
            shuttingDown = true;
            let shutdownExitCode = 0;
            try {
                keyboardHandler?.stop();
                shutdownController.abort();
                await stopDevServices([
                    () => disposeConnectedRuntime?.(),
                    () => mcpServer?.stop(),
                    () => devServer?.stop(),
                ], demoMode ? undefined : {
                    connected: Boolean(disposeConnectedRuntime),
                    forceExit: () => {
                        console.log("  ! Shutdown timed out. Run cancellation may not have been saved.");
                        exitProcess(1);
                    },
                });
            }
            catch {
                shutdownExitCode = 1;
                console.log("  ! Cleanup failed. Run cancellation may not have been saved.");
            }
            if (demoMode) {
                doneResolve?.();
                return;
            }
            exitProcess(shutdownExitCode);
        }
        registerTerminationSignals(() => void shutdown());
        if (isProxyMode) {
            return {
                ready: devServer.ready,
                done,
                port: boundPort,
                stop: shutdown,
            };
        }
        const serverUrl = `http://localhost:${boundPort}`;
        console.log();
        for (const line of devReadinessLines({
            appUrl: serverUrl,
            connection: connectedTarget
                ? {
                    apiUrl: connectedDevApiBaseUrl(runtimeAuth.apiBaseUrl),
                    project: connectedTarget.projectSlug,
                    environment: connectedTarget.environmentName,
                    signedIn: preflightIdentity ? authDisplayName(preflightIdentity) : undefined,
                    studioUrl: `${studioBase.replace(/\/$/, "")}/projects/${encodeURIComponent(connectedTarget.projectSlug)}?panels=runs`,
                }
                : undefined,
        }))
            console.log(line);
        if (isVerbose()) {
            const runtimeId = getConnectedLocalRuntime()?.runtimeId;
            if (runtimeId)
                console.log(`    ${dim("Runtime")} ${runtimeId}`);
        }
        const inferenceOptions = listInferenceOptions({
            apiToken: runtimeAuth.apiToken,
            projectSlug: runtimeAuth.projectSlug,
            openaiApiKey: getEnv("OPENAI_API_KEY"),
            openaiBaseUrl: getEnv("OPENAI_BASE_URL"),
            anthropicApiKey: getEnv("ANTHROPIC_API_KEY"),
            googleApiKey: getEnv("GOOGLE_API_KEY") ?? getEnv("GOOGLE_GENERATIVE_AI_API_KEY"),
            mistralApiKey: getEnv("MISTRAL_API_KEY"),
        });
        if (inferenceOptions.length > 0) {
            console.log(`  ${dim("Inference")} ${brand(inferenceOptions.map((option) => option.replace("Veryfront Cloud AI Gateway", `${veryfrontServiceName(connectedDevApiBaseUrl(runtimeAuth.apiBaseUrl))} AI Gateway`)).join(", "))}`);
            if (displayOptions.defaultModel) {
                console.log(`  ${dim("Default model")} ${brand(displayOptions.defaultModel)} (configured)`);
            }
        }
        // The banner reports configured paths, and it must not block Ready on a
        // network round-trip (see `void authReady` above). But an expired stored
        // session still has a nonempty token, so the gateway would be advertised
        // and then fail on first request. The validation is already in flight —
        // let it correct the record rather than delay the banner.
        if (advertisesCloudGateway(inferenceOptions)) {
            void authReady.then(() => {
                if (identity)
                    return;
                console.log(`  ${warning("!")} Veryfront Cloud session is not valid; gateway inference will fail. ` +
                    `Run ${brand("veryfront login")} to renew it.`);
            });
        }
        if (mcpServer && isVerbose()) {
            console.log(`  ${dim("MCP")} ${brand(`http://localhost:${mcpPort}/mcp`)}`);
        }
        console.log(`  Waiting for requests…${isTTY() ? "  Press ? for shortcuts." : ""}`);
        console.log();
        if (open) {
            try {
                await openBrowser(serverUrl);
            }
            catch {
                console.log(`  ${dim("Could not open browser automatically.")}`);
            }
        }
        if (!demoMode) {
            const logs = createDevLogController();
            keyboardHandler = createKeyboardHandler({
                onHelp: () => {
                    console.log();
                    console.log(shortcutsBlock(DEV_SHORTCUTS));
                    console.log();
                },
                onOpen: () => void openBrowser(serverUrl),
                onLogs: () => {
                    const verbose = logs.toggle();
                    console.log(`  Verbose logs ${verbose ? brand("on") : "off"}`);
                },
                onClear: () => console.clear(),
                onQuit: () => void shutdown(),
                onAuth: async () => {
                    await authReady;
                    if (identity) {
                        console.log(`  ${dim(authStatus(identity))}${dim(", press s to select a project")}`);
                        return;
                    }
                    console.log(`  ${dim("Opening browser...")}`);
                    const result = await loginForDevShortcut(() => login(undefined, getEnvironmentConfig(), projectDir, createConnectedDevAuthenticationOptions(connectedDevApiBaseUrl(runtimeAuth.apiBaseUrl))));
                    if (!result)
                        return;
                    identity = result;
                    const projectResult = await preloadDevAuth(undefined, projectDir);
                    projects = projectResult.projects;
                    console.log(`  ✓ ${authStatus(identity)}${dim(`, ${projects.length} projects`)}`);
                },
                onSync: () => void projectSelector.open(),
                onPull: async () => {
                    const project = selectedProject;
                    if (!project) {
                        console.log(`  Press ${brand("s")} to select a project`);
                        return;
                    }
                    console.log(`  ${dim("Pulling...")}`);
                    await runSyncAction(() => pullCommand({
                        projectSlug: project.slug,
                        projectDir,
                        force: true,
                        quiet: true,
                        transport: createConnectedDevSyncTransport(connectedDevApiBaseUrl(runtimeAuth.apiBaseUrl)),
                    }), "Pulled");
                },
                onPush: async () => {
                    const project = selectedProject;
                    if (!project) {
                        console.log(`  Press ${brand("s")} to select a project`);
                        return;
                    }
                    console.log(`  ${dim("Pushing...")}`);
                    const pushOptions = createSelectedProjectPushOptions(projectDir, project);
                    await runSyncAction(() => pushCommand({
                        ...pushOptions,
                        transport: createConnectedDevSyncTransport(connectedDevApiBaseUrl(runtimeAuth.apiBaseUrl)),
                    }), `Pushed to ${pushOptions.branch} ${dim("- merge in Studio")}`);
                },
            });
            keyboardHandler.start();
        }
        return {
            ready: devServer.ready,
            done,
            port: boundPort,
            stop: shutdown,
        };
    }, {
        "cli.port": options.port,
        "cli.projectDir": options.projectDir,
        "cli.hmr": options.hmr ?? true,
        "cli.open": options.open ?? false,
    });
}
